from functools import cache
@cache
def game(a, b):
    if a + b >= 62:
        return 0
    moves = [game(a + 2, b), game(a * 2, b), game(a, b + 2), game(a, b * 2)]
    if 0 in moves:
        return 1
    if min(moves) < 0:
        return -max(x for x in moves if x < 0) + 1
    return -max(moves)
print(min(s for s in range(1, 55) if game(7, s) != -1 and 1 in [game(9, s), game(14, s), game(7, s + 2), game(7, 2 * s)]))

